/**
 * Walks every org that has not been archived, one keyset page at a time, so a
 * sweep covers the whole tenant base regardless of how many there are. Paging
 * on `id` keeps a page boundary stable while orgs come and go between pages.
 */
export async function* iterateLiveOrgIds(
  pageSize: number,
): AsyncGenerator<OrgId> {
  const size = Math.max(1, pageSize);
  let after: string | null = null;

  for (;;) {
    const predicates = [isNull(organizations.archivedAt)];
    if (after !== null) predicates.push(gt(organizations.id, after));

    const rows = getDb()
      .select({ id: organizations.id })
      .from(organizations)
      .where(and(...predicates))
      .orderBy(asc(organizations.id))
      .limit(size)
      .all();

    for (const row of rows) yield brandId<OrgId>(row.id);
    if (rows.length < size) return;

    after = rows[rows.length - 1].id;
  }
}

